const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5A8.5 8.5 0 0 1 10.5 3H21Z"/><path d="M7 9h9M7 13h6"/>',tasks:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M9 4V2h6v2M8 10l1 1 2-2m2 1h3M8 16l1 1 2-2m2 1h3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',library:'<rect x="4" y="3" width="6" height="18" rx="1"/><path d="M7 6v1m-2 10h4M13 4l5-1 4 17-5 1Z"/>',memory:'<path d="M9 4a3 3 0 0 0-5 2 4 4 0 0 0-1 7 4 4 0 0 0 5 6 3 3 0 0 0 4 1V5a3 3 0 0 0-3-1Zm6 0a3 3 0 0 1 5 2 4 4 0 0 1 1 7 4 4 0 0 1-5 6 3 3 0 0 1-4 1"/><path d="M7 8c4 0 5 3 5 4m5-4c-4 0-5 3-5 4M5 14c3-1 6 0 7 3m7-3c-3-1-6 0-7 3"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',automation:'<path d="M4 7h13l-3-3m6 13H7l3 3M4 7v5m16 5v-5"/><path d="m12 9-3 4h4l-1 3 4-5h-4Z"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',settings:'<path d="m10 3-1 3-3 1-3 3 2 3-1 3 3 3 3-1 3 2 3-2 3-1 1-4-2-2-1-3-4-1-1-2Z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M12 20V4m-6 6 6-6 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h3m4 0h3m-10 4h3"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',user:'<circle cx="12" cy="8" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',check:'<path d="m5 12 4 4L19 6"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m7 3 14 9L7 21Z"/>',file:'<path d="M5 3h9l5 5v13H5Zm9 0v6h5M8 13h8m-8 4h6"/>',link:'<path d="m10 8 3-3a4 4 0 0 1 6 6l-3 3M8 10l-3 3a4 4 0 0 0 6 6l3-3m-6 0 8-8"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',edit:'<path d="m15 3 6 6-12 12H3v-6Zm-12 18 6-6m4-10 6 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',pin:'<path d="m15 3 6 6-4 1-4 5-4-4 5-4ZM9 15l-6 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H4v17h17v-7"/>'};
const icon=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.spark}</svg>`;
const mark=()=>'<svg class="mark" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 15C-1-3 32-3 16 15ZM17 16C35-1 35 32 17 16ZM16 17C33 35 0 35 16 17ZM15 16C-3 33-3 0 15 16Z"/></svg>';
let modalDirty=false;
let S, page=location.hash.slice(1)||'home', tab='runs', libraryTab='all', settingsTab='connections', selectedDoc=null,selectedChat=null,selectedAction=null, filter='',taskFilter='all', archived=false,busy=false, lastFocus=null,modalSubmit=null,pollTimer;
const btn=(label,act,id='',kind='',ico='')=>`<button class="btn ${kind}" data-act="${act}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${esc(label)}</button>`;
const badge=(state)=>`<span class="badge ${['Pending','Waiting for approval','Paused','Draft','Stale','Attention required'].includes(state)?'warn':['Failed','Denied','Canceled','Outcome unknown'].includes(state)?'error':['Disabled','Info','Tested'].includes(state)?'neutral':''}">${esc(state)}</span>`;
const fmt=(time,withDate=false)=>time?new Intl.DateTimeFormat('en-GB',{timeZone:S.settings.timezone,...(withDate?{day:'numeric',month:'short'}:{}),hour:'2-digit',minute:'2-digit'}).format(time):'Not run yet';
const ago=time=>{const m=Math.floor((Date.now()-time)/60000);return m<1?'Just now':m<60?m+' min ago':m<1440?Math.floor(m/60)+' hours ago':Math.floor(m/1440)+' days ago'};
const empty=(title,desc,action='',act='',ico='spark')=>`<div class="empty"><div class="tile-icon green">${icon(ico)}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action?btn(action,act,'','primary'):''}</div>`;
function markdown(value){return esc(value).split('\n').map(l=>l.startsWith('# ')?`<h1>${l.slice(2)}</h1>`:l.startsWith('## ')?`<h2>${l.slice(3)}</h2>`:l.startsWith('### ')?`<h3>${l.slice(4)}</h3>`:l.startsWith('- ')?`<div>• ${l.slice(2)}</div>`:`${l}<br>`).join('');}
async function api(op,data={}){const res=await fetch('/api/'+op,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const body=await res.json();if(!res.ok)throw new Error(body.error||'Request failed.');return body;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
async function refresh(renderNow=true){const r=await fetch('/api/state');const data=await r.json();if(!r.ok)throw new Error(data.error);S=data;if(renderNow)render();schedulePoll();}
function schedulePoll(){clearTimeout(pollTimer);if(S?.runs.some(r=>['Queued','Running'].includes(r.state)))pollTimer=setTimeout(async()=>{try{await refresh(!$('#modal').open);}catch(e){toast(e.message);}},1500);}
async function mutate(op,data={},message='Saved'){await api(op,data);await refresh();if(message)toast(message);}
function go(p){page=p;filter='';selectedDoc=null;location.hash=p;render();window.scrollTo(0,0);}
function header(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function layout(content){const nav=[['home','Home','home'],['chat','Chat','chat'],['tasks','Tasks','tasks'],['approvals','Approvals','shield'],['library','Library','library'],['memory','Memory','memory'],['skills','Skills','spark'],['automations','Automations','automation'],['activity','Activity','activity']];const pending=S.actions.filter(a=>a.state==='Pending').length;return `<aside class="sidebar" id="sidebar"><a class="brand" href="#home">${mark()}daylight</a><div class="workspace-label">Your personal workspace</div><button class="btn primary" style="margin:0 8px 16px" data-act="new-chat">${icon('plus')} New chat</button><nav aria-label="Workspace navigation">${nav.map(([p,label,i],n)=>`${n===4?'<div class="nav-label">YOUR WORKSPACE</div>':''}<button class="nav-item ${page===p?'active':''}" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(i)}${label}${p==='approvals'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item ${page==='settings'?'active':''}" data-page="settings">${icon('settings')}Settings</button><div class="private-note">${icon('lock')} Your work. Your control.<br>External actions need your approval.</div><button class="profile" data-act="profile" style="width:100%;text-align:left"><span class="avatar">${esc(S.settings.name.slice(0,1).toUpperCase())}</span><span><span class="name">${esc(S.settings.name)}</span><div class="sub">${S.demo?'Demo workspace':'Private workspace'}</div></span>${icon('more')}</button></div></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-act="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span><span>${esc(page[0].toUpperCase()+page.slice(1))}</span></div><div class="top-right"><button class="search-launch" data-act="search">${icon('search')}<span>Search your workspace</span><kbd>⌘ K</kbd></button><button class="icon-btn" data-act="notifications" aria-label="Notifications">${icon('bell')}${notificationAttention()?'<i class="dot"></i>':''}</button><span style="height:20px;border-left:1px solid #e5e9ed"></span><span class="small muted status-label" style="font-size:10px">${icon('lock')} Private</span></div></header>${S.demo?`<div class="demo-banner">${icon('info')} Demo workspace <span class="long-demo">· Fictional data and simulated email delivery${!S.model.configured?' · Template generation':''}</span><span class="actions"><button data-act="reset-demo">Reset demo</button><button data-act="leave-demo">Leave demo ${icon('arrow')}</button></span></div>`:''}${S.settings.paused?'<div class="demo-banner">All work is paused. Pending approvals are invalidated.<span class="actions"><button data-act="pause-all">Lift global pause</button></span></div>':''}<main class="content" id="main">${content}</main></div>`;}
function home(){const hour=Number(new Intl.DateTimeFormat('en',{timeZone:S.settings.timezone,hour:'numeric',hourCycle:'h23'}).format(new Date()));const greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';const pending=S.actions.filter(a=>a.state==='Pending');const recent=S.documents.slice(0,3);const meetings=S.meetings;return `${header(greeting+', '+S.settings.name+'.','A little context. A clearer day.',`<div class="date-pill">${icon('calendar')}${new Intl.DateTimeFormat('en-GB',{timeZone:S.settings.timezone,weekday:'long',day:'numeric',month:'long'}).format(new Date())}</div>`)}<div class="home-grid"><div><section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR DAY, WITH A LITTLE MORE SPACE</div><h2>Less catching up.<br>More moving forward.</h2><p>Let’s get you ready for what’s next. I can gather the context, connect the dots, and help you follow through.</p></div><div class="orb-art" aria-hidden="true"><div class="sun"></div><div class="arc"></div><div class="arc two"></div><div class="hill"></div><div class="hill two"></div><span class="sparkle">✧</span></div><form id="home-composer" class="composer"><textarea name="prompt" aria-label="Ask your assistant" placeholder="What would you like a hand with?" required></textarea><div class="composer-footer"><button type="button" class="icon-btn" data-act="upload" aria-label="Add a source">${icon('plus')}</button><span class="composer-note">${icon('shield')} You choose the context. You stay in control.</span><button class="send-btn" type="submit" aria-label="Send request">${icon('up')}</button></div></form><div class="shortcut-row"><button class="shortcut" data-act="prepare">${icon('calendar')} Prepare for a meeting</button><button class="shortcut" data-act="followup">${icon('mail')} Draft a follow-up</button><button class="shortcut" data-act="daily">${icon('sun')} Plan my day</button></div></section><div class="metrics"><div class="metric"><span class="tile-icon purple">${icon('calendar')}</span><div><strong>${meetings.length}</strong><p>Upcoming meetings</p></div></div><div class="metric"><span class="tile-icon green">${icon('tasks')}</span><div><strong>${S.todos.filter(t=>!t.done).length}</strong><p>Open personal tasks</p></div></div><div class="metric"><span class="tile-icon orange">${icon('shield')}</span><div><strong>${pending.length}</strong><p>Waiting for approval</p></div></div></div><section><div class="section-head"><h2>Your upcoming meetings <span class="pill">${meetings.length}</span></h2><button class="text-link" data-act="calendar-settings">Manage calendar ${icon('arrow')}</button></div>${meetings.length?`<div class="meeting-list">${meetings.map((m,i)=>`<div class="meeting"><div class="meeting-time">${esc(m.time)}<small>${m.duration} min</small></div><div class="meeting-info ${m.color==='green'?'green-line':m.color==='orange'?'orange-line':''}"><h3>${esc(m.title)}</h3><p>${icon('user')}${esc(m.person)} <span>·</span> ${esc(m.kind)}</p></div>${btn('Prepare','prepare',m.id,i===0?'soft':'','spark')}</div>`).join('')}</div><div class="small muted" style="font-size:9px;margin-top:9px">Times in ${esc(S.settings.timezone)}${S.demo?' · Fictional demo calendar':''}</div>`:empty('Make room for a prepared day','Connect a selected calendar, or explore the complete flow with fictional demo data.',S.demo?'Add sources':'Try the demo',S.demo?'upload':'demo','calendar')}</section><section class="recent"><div class="section-head"><h2>Recently worked on</h2><button class="text-link" data-page="library">Open library ${icon('arrow')}</button></div>${recent.length?recent.map(d=>`<button class="recent-row" data-act="open-doc" data-id="${d.id}"><span class="tile-icon ${d.type==='Draft'?'orange':'green'}">${icon(d.type==='Draft'?'mail':'file')}</span><span><h3>${esc(d.title)}</h3><p>${esc(d.type)} · ${ago(d.created)}</p></span>${icon('arrow','arrow')}</button>`).join(''):empty('A home for the useful things','Meeting briefs and follow-up drafts will appear here when they’re ready.','','','file')}</section></div><aside class="rail"><div class="rail-card approval-card"><h2>${icon('shield')} You’re in control ${pending.length?'<span class="count">'+pending.length+'</span>':''}</h2><div class="mini-label">${pending.length?'YOUR REVIEW IS NEEDED':'NOTHING WAITING ON YOU'}</div><h3>${pending.length?'A follow-up is ready to send':'A clear approval queue.'}</h3><p>${pending.length?'Take a moment to review the exact email before it goes anywhere.':'Every outgoing email will wait for your explicit approval.'}</p>${btn(pending.length?'Review draft':'How approvals work',pending.length?'review-approval':'approval-info',pending[0]?.id||'','','shield')}</div><div class="rail-card"><div class="focus-head"><h2>Keep in focus</h2><button class="icon-btn" data-act="add-todo" aria-label="Add a personal task">${icon('plus')}</button></div>${S.todos.slice(0,3).map(t=>`<div class="todo-mini ${t.done?'completed':''}"><button class="check ${t.done?'done':''}" data-act="toggle-todo" data-id="${t.id}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}">${t.done?icon('check'):''}</button><div><h4>${esc(t.title)}</h4><p>${t.done?'Completed':t.due?'Due '+esc(t.due):'No due date'}</p></div></div>`).join('')||'<p class="muted small" style="margin-top:15px;font-size:11px">The next useful step belongs here.</p>'}<button class="rail-footer" data-page="tasks">View personal tasks ${icon('arrow')}</button></div><div class="rail-card"><div class="focus-head"><h2>A little behind the scenes</h2>${icon('activity')}</div>${S.activity.slice(0,3).map(a=>`<div class="activity-mini"><h4>${esc(a.title)}</h4><p>${ago(a.created)}</p></div>`).join('')||'<p class="small muted" style="margin-top:15px">Your assistant’s actions will appear here.</p>'}<button class="rail-footer" data-page="activity">Open activity ${icon('arrow')}</button></div><div class="system-note">${icon(S.setup.heartbeat?'activity':'info')}<span>${S.demo?'A safe space to explore. Demo emails never leave this workspace.':S.setup.heartbeat?`Last worker heartbeat ${ago(S.setup.heartbeat)}. ${Date.now()-S.setup.heartbeat>300000?'Worker degraded.':''}`:'Background worker not connected. Schedules will show this until deployment setup is complete.'}<br><button class="select-link" data-act="pause-all">${S.settings.paused?'Lift global pause':'Pause all work'}</button></span></div></aside></div><div class="bottom-note">${icon('lock')} Thoughtful assistance. Explicit permission. Always your call.</div>`;}
function tasks(){const list=S.runs.filter(r=>(taskFilter==='all'||r.state===taskFilter)&&(!filter||r.prompt.toLowerCase().includes(filter)));return `${header('A clear view of your work.','See what your assistant is doing, and keep your own next steps close.',btn('Add personal task','add-todo','','primary','plus'))}<div class="tabs"><button class="tab ${tab==='runs'?'active':''}" data-tab="runs">Assistant runs <span class="muted">${S.runs.length}</span></button><button class="tab ${tab==='todos'?'active':''}" data-tab="todos">Personal tasks <span class="muted">${S.todos.length}</span></button></div><div class="toolbar"><input class="input-search" id="filter" placeholder="Search ${tab==='runs'?'runs':'tasks'}…" value="${esc(filter)}" aria-label="Search tasks"><select class="filter-select" id="task-filter" aria-label="Filter by status">${(tab==='runs'?['all','Queued','Running','Waiting for approval','Succeeded','Failed','Paused','Canceled']:['all','open','completed','overdue']).map(x=>`<option ${taskFilter===x?'selected':''}>${x}</option>`).join('')}</select></div>${tab==='runs'?(list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Run & outcome</th><th>Status</th><th>Started</th><th>Actions</th></tr></thead><tbody>${list.map(r=>`<tr><td><button class="title" data-act="open-run" data-id="${r.id}">${esc(r.prompt)}</button><div class="sub">${esc(S.skills.find(k=>k.id===r.skill)?.name||'Conversation')}${r.test?' · Test run':''}${r.automation?' · Scheduled workflow':''}</div></td><td>${badge(r.state)}</td><td class="muted">${fmt(r.started||r.created,true)}</td><td><div class="row-actions">${r.document?btn('Open output','open-doc',r.document,'small'):btn('Inspect','open-run',r.id,'small')}${['Queued','Running'].includes(r.state)?btn('Pause','pause-run',r.id,'small'):['Failed','Paused'].includes(r.state)?btn('Resume','resume-run',r.id,'small'):''}${!['Succeeded','Canceled'].includes(r.state)?btn('Cancel','cancel-run',r.id,'small danger'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Nothing running in the background','Start with a meeting brief, a daily overview, or a question in Chat.','Start a conversation','new-chat','tasks')):renderTodos()}`;}
function renderTodos(){const today=new Date().toISOString().slice(0,10);const todos=S.todos.filter(t=>(!filter||t.title.toLowerCase().includes(filter))&&(taskFilter==='all'||taskFilter==='open'&&!t.done||taskFilter==='completed'&&t.done||taskFilter==='overdue'&&!t.done&&t.due&&t.due<today));return todos.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Personal task</th><th>Due date</th><th>Status</th><th>Actions</th></tr></thead><tbody>${todos.map(t=>`<tr><td><div class="row"><button class="check ${t.done?'done':''}" data-act="toggle-todo" data-id="${t.id}" aria-label="${t.done?'Reopen':'Complete'} task">${t.done?icon('check'):''}</button><div><div class="title">${esc(t.title)}</div><div class="sub">${esc(t.notes)}</div></div></div></td><td class="muted">${esc(t.due)||'No due date'}</td><td>${badge(t.done?'Completed':t.due&&t.due<today?'Overdue':'Open')}</td><td><div class="row-actions">${btn('Edit','edit-todo',t.id,'small')}${btn('Delete','delete-todo',t.id,'small danger')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('A little space for your next step','These are personal to-dos inside Daylight. Add a task, set a date, and move it forward.','Add a task','add-todo','tasks');}
function memories(){const items=S.memories.filter(m=>!filter||m.text.toLowerCase().includes(filter));return `${header('A little less to repeat.','Only the things you choose to save. Always visible, always yours to change.',btn('Add memory','add-memory','','primary','plus'))}${!S.settings.memory?'<div class="callout warn">'+icon('info')+'Saved memory is turned off globally. These memories will not influence new runs.</div>':''}<div class="toolbar"><input class="input-search" id="filter" aria-label="Search memories" placeholder="Search your memories…" value="${esc(filter)}"><span class="muted small">${S.memories.filter(m=>m.state==='Active').length} active memories</span></div>${items.length?`<div class="cards">${items.map(m=>`<article class="card memory-card ${m.state==='Disabled'?'disabled':''}"><div class="row between"><span class="tile-icon ${m.type==='Preference'?'purple':'green'}">${icon('memory')}</span><span class="row">${m.pinned?icon('pin'):''}${badge(m.state)}</span></div><div class="quote">${esc(m.text)}</div><div class="muted small">${esc(m.type)} · ${esc(m.scope)}</div><div class="small muted" style="font-size:9px;margin-top:10px;line-height:1.8">${esc(m.origin)}<br>Version ${m.version} · Saved ${fmt(m.created,true)}</div><div class="card-actions">${btn('Edit','edit-memory',m.id,'small')}${btn(m.pinned?'Unpin':'Pin','pin-memory',m.id,'small')}${btn(m.state==='Active'?'Disable':'Enable','toggle-memory',m.id,'small')}${btn('Forget','delete-memory',m.id,'small danger')}</div></article>`).join('')}</div>`:empty('You decide what stays','Save a preference to shape future briefs and drafts. Nothing is inferred and saved without your review.','Add a preference','add-memory','memory')}`;}
function library(){if(selectedDoc){const d=S.documents.find(x=>x.id===selectedDoc);if(d)return documentDetail(d);selectedDoc=null;}const all=[...S.documents,...S.sources.map(x=>({...x,isSource:true}))].filter(d=>(libraryTab==='all'||libraryTab==='sources'&&d.isSource||libraryTab==='drafts'&&d.type==='Draft'||libraryTab==='briefs'&&d.type==='Brief')&&(!filter||d.title.toLowerCase().includes(filter)));return `${header('The useful things, in one place.','Meeting context, thoughtful drafts, and the source material behind them.',btn('Upload sources','upload','','primary','upload'))}<div class="tabs">${[['all','All items'],['briefs','Briefs'],['drafts','Drafts'],['sources','Sources']].map(([v,l])=>`<button class="tab ${libraryTab===v?'active':''}" data-library-tab="${v}">${l}</button>`).join('')}</div><div class="toolbar"><input class="input-search" id="filter" aria-label="Search library" placeholder="Search your library…" value="${esc(filter)}"><span class="muted small">${all.length} items</span></div>${all.length?`<div class="cards">${all.map(d=>`<article class="card"><div class="row between"><span class="tile-icon ${d.type==='Draft'?'orange':d.isSource?'purple':'green'}">${icon(d.type==='Draft'?'mail':'file')}</span>${badge(d.isSource?d.active?'Ready':'Excluded':d.type)}</div><h3>${esc(d.title)}</h3><p style="font-size:11px;min-height:55px">${esc(d.text.slice(0,140)).replaceAll('\n',' ')}${d.text.length>140?'…':''}</p><div class="small muted" style="margin-top:16px;font-size:9px">Version ${d.version} · ${fmt(d.created,true)}</div><div class="card-actions">${btn('Open','open-'+(d.isSource?'source':'doc'),d.id,'small','arrow')}${btn('Download','download-'+(d.isSource?'source':'doc'),d.id,'small','download')}${btn('Delete','delete-'+(d.isSource?'source':'doc'),d.id,'small danger')}</div></article>`).join('')}</div>`:empty('Start with a little context','Upload text, Markdown, or a PDF with selectable text. Generated briefs and drafts will live here too.','Upload a source','upload','library')}`;}
function documentDetail(d){return `<div class="section-head"><button class="text-link" data-act="library-back">← Back to library</button><div class="row-actions">${btn('Edit','edit-doc',d.id,'small','edit')}${btn('Duplicate','duplicate-doc',d.id,'small')}${btn('Download','download-doc',d.id,'small','download')}</div></div><article class="detail-panel"><div class="row between"><h2>${esc(d.title)}</h2>${badge(d.type)}</div><div class="metadata">Version ${d.version} · ${fmt(d.created,true)} · ${esc(d.model||'App draft')}${d.edited?' · User edited · citations removed from changed content':''}</div>${d.type==='Draft'?`<div class="muted-box" style="margin-top:22px"><strong>To</strong> ${esc(d.to)}<br><strong>Subject</strong> ${esc(d.subject)}</div>`:''}<div class="doc-body">${markdown(d.text)}</div>${d.type==='Draft'?'<div class="word-count">'+d.text.trim().split(/\s+/).length+' words · App draft, not a Gmail draft</div>':''}${d.references?.length?`<hr class="divider"><h3 class="small">Sources used</h3><div style="margin-top:11px">${d.references.map(ref=>{const rid=ref.id||ref;const src=S.sources.find(s=>s.id===rid);return `<button class="source-chip" data-act="open-source" data-id="${esc(rid)}" data-version="${ref.version||1}">${icon('link')}${esc(src?.title||'Source unavailable')}${ref.version?' · v'+ref.version:''}</button>`}).join('')}</div>`:''}${d.memoryUsed?.length?`<div class="memory-used">${icon('memory')} Memory used in this output<br>${d.memoryUsed.map(m=>'• '+esc(m.text)+(S.memories.some(x=>x.id===m.id)?'':' · now forgotten')).join('<br>')}</div>`:''}<div class="foot-actions">${d.run?btn('Inspect run','open-run',d.run):''}${d.type==='Draft'?btn('Request send approval','request-approval',d.id,'primary','shield'):btn('Draft a follow-up','followup-from',d.id,'primary','mail')}${btn('Save as skill','save-as-skill',d.id)}</div></article>`;}
function skills(){return `${header('Good workflows, worth keeping.','Small, reusable recipes for the work you do again and again.',btn('Create a skill','new-skill','','primary','plus'))}<div class="callout">${icon('shield')}Skills use a fixed set of tools. They cannot grant permissions, run arbitrary code, or approve an external action.</div><div class="cards">${S.skills.map(k=>`<article class="card"><div class="row between"><span class="tile-icon ${k.color||'purple'}">${icon(k.icon||'spark')}</span>${badge(k.state)}</div><h3>${esc(k.name)}</h3><p>${esc(k.description)}</p><div class="small muted" style="font-size:9px;margin-top:17px">${k.builtin?'Daylight built-in':'Personal skill'} · Version ${k.version} · ${k.id==='followup'?'Email draft · send needs approval':'Read sources · create internal output'}</div><div class="card-actions">${k.state==='Active'?btn('Run skill','run-skill',k.id,'small primary','play'):k.state==='Draft'?btn('Test','test-skill',k.id,'small primary'):k.state==='Tested'?btn('Activate','activate-skill',k.id,'small primary'):btn('Re-enable','activate-skill',k.id,'small primary')}${!k.builtin?btn('Edit','edit-skill',k.id,'small'):''}${btn('Duplicate','duplicate-skill',k.id,'small')}${k.state==='Active'?btn('Disable','disable-skill',k.id,'small'):''}${!k.builtin?btn('Delete','delete-skill',k.id,'small danger'):''}</div></article>`).join('')}</div>`;}
function automations(){const healthy=S.setup.heartbeat&&Date.now()-S.setup.heartbeat<300000;return `${header('A little help, on your schedule.','Prepare ahead with a saved workflow. Outgoing emails still wait for approval.',btn('New automation','new-automation','','primary','plus'))}<div class="callout ${healthy?'':'warn'}">${icon('activity')}${healthy?'Worker heartbeat '+ago(S.setup.heartbeat)+'. Enabled schedules run without this browser open.':'Background worker '+(S.setup.heartbeat?'degraded · last heartbeat '+ago(S.setup.heartbeat):'not connected')+'. Schedules are saved, but unattended execution is not verified. Connect the authenticated scheduler in deployment setup.'}</div>${S.automations.length?`<div class="stack">${S.automations.map(a=>`<article class="card"><div class="row between"><div class="row"><span class="tile-icon green">${icon('automation')}</span><div><h3 style="margin:0 0 6px">${esc(a.name)}</h3><p style="font-size:10px">${esc(S.skills.find(k=>k.id===a.skill)?.name||'Unavailable skill')} · Pinned to version ${a.version}</p></div></div>${badge(a.state)}</div><hr class="divider"><div class="two-col"><div><p style="font-size:11px;color:#7a8795">${a.recurrence==='once'?'Once':a.recurrence==='daily'?'Every day':'Every weekday'} at ${esc(a.time)} · ${esc(a.timezone)}</p><p style="font-size:10px;margin-top:7px">Next: ${a.next?.[0]?new Intl.DateTimeFormat('en-GB',{timeZone:a.timezone,dateStyle:'medium',timeStyle:'short'}).format(a.next[0]):'No future occurrence'}</p></div><div class="small muted" style="font-size:10px;line-height:1.9">Creates an internal output · ${a.sources?.length||0} selected sources<br>Last run: ${a.lastRun?fmt(a.lastRun,true):'Not run yet'}${S.demo?'<br>Demo schedules run manually; no unattended fixture work.':''}</div></div><div class="card-actions">${btn('Run now','run-automation',a.id,'small primary','play')}${btn(a.state==='Enabled'?'Pause':'Enable','toggle-automation',a.id,'small',a.state==='Enabled'?'pause':'play')}${btn('Edit','edit-automation',a.id,'small','edit')}${btn('Delete','delete-automation',a.id,'small danger')}</div></article>`).join('')}</div>`:empty('Make a useful routine','Choose a tested skill, review its context, and give it a time. Start with a weekday morning brief.','Create a schedule','new-automation','automation')}`;}
function approvals(){const a=S.actions.find(x=>x.id===selectedAction)||S.actions.find(x=>x.state==='Pending')||S.actions[0];return `${header('Your say, before send.','Review the exact message. One approval, one action.')}<div class="approval-layout"><div class="approval-list">${S.actions.map(x=>`<button class="approval-item ${a?.id===x.id?'active':''}" data-act="select-approval" data-id="${x.id}">${badge(x.state==='Pending'&&x.expires<Date.now()?'Expired':x.state)}<h3>${esc(x.payload.subject)}</h3><p>${esc(x.payload.to)}</p><p style="margin-top:7px">${fmt(x.created,true)}</p></button>`).join('')||empty('All clear','New proposed sends will appear here.','','','shield')}</div><div>${a?approvalDetail(a):empty('Every detail deserves a review','Open a follow-up draft in Library to request approval.','Open library','library-page','mail')}</div></div>`;}
function approvalDetail(a){const expired=a.state==='Pending'&&a.expires<Date.now();return `<section class="detail-panel"><div class="row between"><h2>Email approval</h2>${badge(expired?'Expired':a.state)}</div><div class="metadata">${a.demo?'Simulated Gmail · Demo account':'Gmail · '+esc(S.connections.gmail.account||'Disconnected')}<br>Action ${esc(a.id)} · Draft version ${a.version}<br>Purpose: Send the reviewed follow-up. No outgoing attachments, CC, or BCC.</div>${a.demo?'<div class="callout warn" style="margin-top:20px">'+icon('info')+'Demo delivery is simulated. No message is sent to a real account.</div>':''}<div class="muted-box" style="margin-top:20px"><strong>To</strong> ${esc(a.payload.to)}<br><strong>Subject</strong> ${esc(a.payload.subject)}</div><div class="doc-body">${esc(a.payload.body).replaceAll('\n','<br>')}</div><div class="word-count">${a.payload.body.trim().split(/\s+/).length} words · Exact provider payload</div>${a.receipt?`<div class="receipt">${esc(a.receipt.provider)} receipt<br>Message ID: ${esc(a.receipt.id)}<br>Confirmed: ${fmt(a.receipt.time,true)} · ${esc(S.settings.timezone)}${a.receipt.simulated?'<br>SIMULATED · no external delivery':''}</div>`:''}${a.state==='Outcome unknown'?'<div class="callout warn">'+icon('info')+esc(a.error||'The provider outcome is uncertain. A repeat send is blocked.')+'</div>':''}<hr class="divider"><div class="small muted" style="font-size:10px;line-height:1.9">${a.state==='Pending'?'Approval expires '+fmt(a.expires)+' · '+esc(S.settings.timezone)+'. Editing creates a new version requiring fresh approval.':a.state==='Denied'?'You denied this send. No message was dispatched. The draft remains in Library.':'Completed effects cannot be undone by deleting this request.'}</div><div class="foot-actions">${a.state==='Pending'&&!expired?`${btn('Edit draft','edit-doc',a.document)}${btn('Deny','deny-approval',a.id,'danger')}${btn(a.demo?'Approve simulated send':'Approve and send once','approve-send',a.id,'primary','shield')}`:expired||a.state==='Stale'?btn('Refresh preview','refresh-approval',a.id,'primary'):a.state==='Outcome unknown'?btn('Check status','reconcile',a.id,'primary'):''}</div></section>`;}
function activity(){const rows=S.activity.filter(a=>!filter||(a.title+' '+a.detail+' '+a.tool).toLowerCase().includes(filter));return `${header('What happened, and why.','A factual trail of work, permissions, and results.',btn('Export activity','export-activity','','','download'))}<div class="toolbar"><input class="input-search" id="filter" placeholder="Search events, tools, outcomes…" aria-label="Search activity" value="${esc(filter)}"><span class="small muted">${rows.length} events</span></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Event</th><th>Tool</th><th>Outcome</th><th>Time</th></tr></thead><tbody>${rows.map(a=>`<tr><td><div class="title">${esc(a.title)}</div><div class="sub">${esc(a.detail)}</div></td><td class="muted">${esc(a.tool)}</td><td>${badge(a.state)}</td><td class="muted">${fmt(a.created,true)}<br><span class="tiny">${esc(S.settings.timezone)}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Your workspace has a clean slate','Run a workflow or save a preference to begin the activity trail.','','','activity')}`;}
function chat(){const c=S.chats.find(x=>x.id===selectedChat);const r=c&&S.runs.find(x=>x.id===c.run);const d=r&&S.documents.find(x=>x.id===r.document);return `${header('A thought, a task, a starting point.','Choose what your assistant can use, then work through it together.')}<div class="chat-layout"><aside class="chat-list">${btn('New conversation','new-chat','','small','plus')}<div class="row between" style="margin:20px 0 8px"><span class="eyebrow">${archived?'ARCHIVED':'RECENT CHATS'}</span><button class="select-link" data-act="toggle-archived">${archived?'Recent':'Archived'}</button></div>${S.chats.filter(c=>!!c.archived===archived).map(c=>`<button class="chat-item ${selectedChat===c.id?'active':''}" data-act="select-chat" data-id="${c.id}">${esc(c.title)}</button>`).join('')}</aside><section class="chat-space">${r?`<div class="row between"><span class="small muted">${esc(c.title)}</span><div class="row-actions">${btn('Rename','rename-chat',c.id,'small')}${btn(c.archived?'Restore':'Archive','archive-chat',c.id,'small')}${btn('Delete','delete-chat',c.id,'small danger')}</div></div><div class="chat-message">${esc(r.prompt)}${r.notes?'<br><br>Notes: '+esc(r.notes):''}</div><div class="chat-answer"><div class="row between"><span class="row" style="font-size:12px;font-weight:600">${mark()} Daylight</span>${badge(r.state)}</div>${['Queued','Running'].includes(r.state)?'<div class="progress"></div><p class="small muted">Working with your selected context…</p>':r.error?'<div class="callout warn" style="margin-top:20px">'+esc(r.error)+'</div>':d?`<div class="doc-body">${markdown(d.text)}</div><div class="row-actions">${btn('Open saved output','open-doc',d.id,'small')}${btn('Inspect sources & run','open-run',r.id,'small')}${btn('Regenerate','regenerate',r.id,'small')}</div>`:'<p class="small muted" style="margin-top:20px">'+(r.state==='Canceled'?'This run was canceled.':'No saved output yet.')+'</p>'}</div>`:`<div class="chat-welcome">${mark()}<h2>What’s on your mind?</h2><p>Prepare for a conversation, untangle a next step, or get a clearer picture of your day.</p><div class="shortcut-row" style="justify-content:center;margin-top:22px"><button class="shortcut" data-act="prepare">${icon('calendar')} Prepare for a meeting</button><button class="shortcut" data-act="followup">${icon('mail')} Draft a follow-up</button></div></div>`}<form id="chat-composer" class="composer"><textarea name="prompt" aria-label="Your request" placeholder="Tell me what you’d like to work on…" required></textarea><div class="composer-footer"><button type="button" class="icon-btn" data-act="upload" aria-label="Upload a source">${icon('plus')}</button><span class="composer-note">${S.demo&&!S.model.configured?'Demo templates · no live model':'Selected context only · no automatic sends'}</span><button class="send-btn" type="submit" aria-label="Send request">${icon('up')}</button></div><div class="chat-context"><label><input type="checkbox" name="memory" ${S.settings.memory?'checked':''}>Use saved memory</label>${S.sources.filter(x=>x.active).map(x=>`<label><input type="checkbox" name="sources" value="${x.id}" checked>${esc(x.title)}</label>`).join('')||'<span class="muted">No selected source documents.</span>'}</div></form></section></div>`;}
function settings(){return `${header('Make yourself at home.','Your preferences, your connections, and your boundaries.')}<div class="settings-nav">${['connections','profile','privacy','notifications','usage','deployment'].map(x=>`<button class="${settingsTab===x?'active':''}" data-settings-tab="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="settings-section">${settingsContent()}</div>`;}
function settingsContent(){switch(settingsTab){case 'connections':return `${S.demo?'<div class="callout warn">'+icon('info')+'You’re viewing fictional demo connections. Leave demo to connect a real Google account.</div>':''}<div class="callout">${icon('lock')}Signing into this private Site establishes your workspace identity. Google source access is requested separately and never follows from sign-in.</div>${['gmail','calendar'].map(k=>{const c=S.connections[k];return `<article class="card"><div class="row between"><div class="row"><span class="tile-icon ${k==='gmail'?'orange':'purple'}">${icon(k==='gmail'?'mail':'calendar')}</span><div><h3>${k==='gmail'?'Gmail':'Google Calendar'}</h3><p>${S.demo?'Demo fixture · no real account':esc(c.account||'No account connected')}</p></div></div>${badge(S.demo?'Simulated':c.state)}</div><hr class="divider"><p>${k==='gmail'?'Read selected labels'+(c.send?' · Sending enabled, exact approval required':' · Sending not enabled'):'Read selected calendars · Calendar writes are outside MVP scope'}</p><p style="margin-top:8px">Application filter: ${esc((k==='gmail'?c.labels:c.calendars).join(', '))}<br>Last check: ${c.checked?fmt(c.checked,true):'Not checked'}</p><div class="card-actions">${btn(c.state==='Connected'?'Reconnect / edit access':'Connect '+(k==='gmail'?'Gmail':'Calendar'),'connect',k,'small primary')}${c.state==='Connected'?btn('Refresh context','sync',k,'small'):''}${c.state==='Connected'?btn('Disconnect Google','disconnect','','small danger'):''}</div></article>`}).join('')}<p class="small muted" style="font-size:10px;line-height:1.9">Provider grants can be broader than application filters. This build fetches up to 15 email snippets and 20 events per selected calendar. One Google account is supported.</p>`;
 case 'profile':return `<form id="profile-form"><article class="card"><h3>Your preferences</h3><p>These settings are separate from your saved memories.</p>${field('Display name','name',S.settings.name)}${field('Timezone','timezone',S.settings.timezone,'text','Use an IANA timezone, such as Asia/Kolkata or Europe/London. Existing schedules keep their own timezone.')}<div class="foot-actions"><button class="btn primary" type="submit">Save preferences</button></div></article></form><article class="card"><h3>A separate identity and connection</h3><p>This private Site uses the hosting platform’s sign-in. Google OAuth grants access to selected work sources.</p><div class="card-actions"><a class="btn small" href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a>${btn('Pause all work','pause-all','','small')}</div><p style="margin-top:14px">Signing out does not stop enabled background work.</p></article>`;
 case 'privacy':return `<article class="card"><h3>Remember only what you choose</h3><p>Saved memory influences eligible new runs. Forgetting a memory does not rewrite old outputs or delete external email.</p><label class="checkbox" style="margin-top:20px"><input id="global-memory" type="checkbox" ${S.settings.memory?'checked':''}>Use saved memory in future tasks</label></article><article class="card"><h3>Processing disclosure</h3><p>For live generation, selected source text, your request, and eligible saved memories are sent to the configured Nebius inference service. Processing uses hosted infrastructure.</p><p style="margin-top:12px">Status: ${S.settings.disclosure?'Accepted':'Not yet accepted'}</p>${btn('Review disclosure','disclosure','','small')}</article><article class="card"><h3>Take your work with you</h3><p>Download a JSON snapshot of this workspace. Credentials and Google OAuth tokens are excluded.</p><div class="card-actions">${btn('Export workspace','export-workspace','','small','download')}</div></article><article class="card"><h3>Delete workspace data</h3><p>Remove active app-held records, sources, outputs, and Google credentials. External sent email and downloaded files are unaffected. Hosting backup erasure and session revocation are not verified in this build.</p><div class="card-actions">${btn('Review deletion','erase','','small danger','trash')}</div></article>`;
 case 'notifications':return `<form id="notifications-form"><article class="card"><h3>A quieter kind of assistance</h3><p>Notifications stay inside Daylight. Pending approvals always remain in their queue.</p><label class="checkbox" style="margin-top:22px"><input type="checkbox" name="notifications" ${S.settings.notifications?'checked':''}>Show completion attention indicators</label><label class="checkbox"><input type="checkbox" name="generic" ${S.settings.generic?'checked':''}>Use generic notification previews</label><p style="margin-top:16px">Email, push, and SMS notifications are outside this release.</p><div class="foot-actions"><button class="btn primary" type="submit">Save notifications</button></div></article></form>`;
 case 'usage':return `<div class="two-col"><article class="card"><div class="eyebrow">MODEL REQUESTS</div><h1 style="margin-top:12px">${S.usage.requests}</h1><p>Confirmed inference calls</p></article><article class="card"><div class="eyebrow">REPORTED TOKENS</div><h1 style="margin-top:12px">${S.usage.tokens.toLocaleString()}</h1><p>${S.usage.unknown?'Some provider usage is unknown':'As reported by the provider'}</p></article></div><form id="usage-form"><article class="card" style="margin-top:18px"><h3>Usage boundary</h3><p>The current build enforces a cumulative workspace token ceiling. Monthly resets and exact cost tracking are not yet implemented.</p>${field('Workspace token ceiling','tokenLimit',S.settings.tokenLimit,'number')}<p>Estimated monetary cost: unavailable. A token ceiling is not an exact spending cap.</p><div class="foot-actions"><button class="btn primary" type="submit">Save limit</button></div></article></form>`;
 case 'deployment':return `<article class="card"><div class="row between"><h3>Runtime readiness</h3>${badge(S.model.configured?'Configured':'Setup required')}</div><p>Provider: ${esc(S.model.provider)}<br>NVIDIA model: ${esc(S.model.id)}<br>Last successful inference: ${S.model.lastCheck?fmt(S.model.lastCheck.time,true):'Not verified'}</p><hr class="divider"><p>Google OAuth: ${S.setup.google?'Deployment credentials present':'Deployment credentials required'}<br>Scheduler: ${S.setup.heartbeat?'Last heartbeat '+fmt(S.setup.heartbeat,true):'No authenticated worker heartbeat'}<br>Storage: Server-side D1 database<br>Identity: Private Sites access boundary</p></article><article class="card"><h3>Connect the live services</h3><p>Set runtime secrets in the deployment operator environment. Never paste API keys into Chat, Memory, or source documents.</p><div class="muted-box" style="margin-top:20px;font-family:monospace">NEBIUS_API_KEY<br>NEBIUS_MODEL<br>NEBIUS_BASE_URL (optional)<br>GOOGLE_CLIENT_ID<br>GOOGLE_CLIENT_SECRET<br>GOOGLE_TOKEN_KEY<br>SCHEDULER_SECRET</div><p style="margin-top:18px">Google redirect URI:<br><code>${esc(location.origin)}/oauth/google</code></p><p style="margin-top:14px">Scheduler calls POST /api/tick with its bearer secret every minute. Cron execution is provided in the Worker export; the host must provision its trigger.</p></article><article class="card"><h3>Build status</h3><p>This is an implementation of the main MVP workflows with an isolated demo. Live provider delivery, Google consent verification, closed-browser scheduling, backup erasure, and the full AC01–AC20 release gate require deployment validation.</p></article>`;}}
function render(){if(!S)return;const views={home,chat,tasks,library,memory:memories,skills,automations,approvals,activity,settings};if(!views[page])page='home';$('#app').innerHTML=layout(views[page]());}
function field(label,name,value='',type='text',hint=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`:`<input id="f-${name}" type="${type}" name="${name}" value="${esc(value)}">`}${hint?`<small>${esc(hint)}</small>`:''}</div>`;}
function selectField(label,name,options,value){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(x=>`<option value="${esc(x.value??x)}" ${(x.value??x)===value?'selected':''}>${esc(x.label??x)}</option>`).join('')}</select></div>`;}
function modal(title,body,submit=null,submitLabel='Save',large=false){modalDirty=false;lastFocus=document.activeElement;const el=$('#modal');el.innerHTML=`<div class="dialog-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-act="close-modal" aria-label="Close dialog">${icon('close')}</button></div><form id="modal-form"><div class="error-msg" role="alert" id="modal-error"></div>${body}${submit?`<div class="foot-actions">${btn('Cancel','close-modal')}<button class="btn primary" type="submit">${esc(submitLabel)}</button></div>`:''}</form>`;el.style.width=large?'800px':'590px';modalSubmit=submit;if(!el.open)el.showModal();setTimeout(()=>$('input,textarea,select,button[type=submit]',el)?.focus(),10);}
function closeModal(){modalDirty=false;$('#modal').close();modalSubmit=null;lastFocus?.focus();}
function dataOf(form){return Object.fromEntries(new FormData(form));}
function confirm(title,body,run,label='Confirm'){modal(title,`<p class="dialog-intro">${esc(body)}</p>`,async()=>{await run();closeModal();},label);}
function sourcesPicker(selected=S.sources.filter(x=>x.active).map(x=>x.id)){return `<div class="field"><label>Selected sources</label><div class="scope-list">${S.sources.filter(x=>x.active&&x.state==='Ready').map(x=>`<label class="checkbox"><input type="checkbox" name="sources" value="${x.id}" ${selected.includes(x.id)?'checked':''}>${esc(x.title)}</label>`).join('')||'<span class="small muted">No ready sources. Add text in Library to provide context.</span>'}</div></div><label class="checkbox"><input name="memory" type="checkbox" ${S.settings.memory?'checked':''}>Use saved memory</label>`;}
async function ensureDisclosure(next){if(S.settings.disclosure||S.demo&&!S.model.configured)return next();modal('Your context, with your consent.',`<p class="dialog-intro">To generate a live response, Daylight sends your request, selected source text, and eligible saved memories to the configured Nebius inference service. Hosted processing is required. You can change selected sources and turn off memory for each task.</p><label class="checkbox"><input type="checkbox" name="accept" required>I understand and agree to this processing.</label>`,async(_,form)=>{if(!$('[name=accept]',form).checked)throw new Error('Accept the disclosure to continue.');await api('settings',{settings:{disclosure:true}});await refresh(false);closeModal();await next();},'Accept and continue');}
async function startRun(b){const result=await api('run',b);await refresh(false);selectedChat=S.chats.find(x=>x.run===result.run)?.id;page='chat';location.hash='chat';render();closeModal();toast('Request started. Your saved run will stay here.');}
function runModal(skillId,meetingId='',test=false){const k=S.skills.find(x=>x.id===skillId);if(!k)return;if(skillId==='meeting'&&!S.meetings.length){modal('A little context first.',`<p class="dialog-intro">There are no permitted calendar events available. Connect Calendar and refresh it in Settings, or try the fictional demo workspace.</p><div class="foot-actions">${btn('Open connections','connections-modal','','primary')}${!S.demo?btn('Try demo','demo'):''}</div>`);return;}ensureDisclosure(()=>{modal(test?'Test '+k.name:k.name,`<p class="dialog-intro">${esc(k.description)}${test?' This test creates an internal output. It cannot send email.':''}</p>${['meeting','followup'].includes(skillId)?selectField('Meeting','meeting',S.meetings.map(m=>({value:m.id,label:m.title+' · '+m.time})),meetingId||S.meetings[0]?.id):''}${skillId==='followup'?field('Meeting notes or outcome','notes','','textarea','Only the notes you provide will be treated as meeting outcomes.')+field('Recipient email','to',S.meetings.find(m=>m.id===meetingId)?.email||S.meetings[0]?.email||'','email'):''}${!['meeting','followup','daily'].includes(skillId)?field('Your request or inputs','prompt','','textarea'):''}${sourcesPicker()}`,async(d,f)=>{await startRun({...d,skill:skillId,test,prompt:d.prompt||k.name,sources:new FormData(f).getAll('sources'),memory:$('[name=memory]',f).checked});},test?'Run safe test':'Start workflow');});}
function editTodo(t={}){modal(t.id?'Edit personal task':'A useful next step.',`${field('Task title','title',t.title)}${field('Notes','notes',t.notes,'textarea')}<div class="field-row">${field('Due date','due',t.due,'date')}<div class="field"><label>Timezone</label><div class="muted-box">${esc(S.settings.timezone)}</div></div></div><p class="small muted">Personal tasks stay inside Daylight. Saving does not assign work to anyone else.</p>`,async d=>{await mutate('todo-save',{...d,id:t.id},'Personal task saved.');closeModal();});}
function editMemory(m={}){modal(m.id?'Edit a saved memory':'One less thing to repeat.',`${field('What would you like Daylight to remember?','text',m.text,'textarea')}${selectField('Type','type',['Preference','Fact'],m.type||'Preference')}${selectField('Use in','scope',['All tasks',...S.skills.map(k=>k.name)],m.scope||'All tasks')}<p class="small muted">Saving is an explicit choice. Never store passwords or API keys here.</p>`,async d=>{await mutate('memory-save',{...d,id:m.id},'Memory saved for eligible future runs.');closeModal();});}
function editDoc(d){if(!d){toast('This draft is no longer available.');return;}modal('Make it yours.',`${field('Document title','title',d.title)}${d.type==='Draft'?field('To · one complete email address','to',d.to,'email')+field('Subject','subject',d.subject):''}${field('Content','text',d.text,'textarea')}<p class="small muted">Saving creates version ${d.version+1}, invalidates previous approvals, and marks this content as user-edited.</p>`,async data=>{await mutate('document-save',{...data,id:d.id},'New version saved. Previous approvals are invalid.');closeModal();},'Save new version',true);}
function editSkill(k={}){modal(k.id?'Edit skill · new draft':'Keep a good workflow.',`${field('Skill name','name',k.name)}${field('Purpose','description',k.description)}${field('Declarative instructions','instructions',k.instructions,'textarea','Only selected source reads and internal text generation are available. Sends always require separate approval.')}<p class="small muted">Save as a draft, run a safe test, then activate. Existing automations remain pinned to their old version.</p>`,async d=>{await mutate('skill-save',{...d,id:k.id},'Skill draft saved. Test this version before activation.');closeModal();});}
function editAutomation(a={}){const active=S.skills.filter(k=>k.state==='Active');if(!active.length){toast('Activate a tested skill first.');return;}modal(a.id?'Edit your routine':'A small routine. A clearer day.',`${field('Automation name','name',a.name)}${selectField('Tested skill version','skill',active.map(k=>({value:k.id,label:k.name+' · v'+k.version})),a.skill||'daily')}${selectField('Repeat','recurrence',[{value:'weekdays',label:'Weekdays'},{value:'daily',label:'Every day'},{value:'once',label:'One time'}],a.recurrence||'weekdays')}<div class="field-row">${field('Local time','time',a.time||'08:30','time')}${field('Timezone','timezone',a.timezone||S.settings.timezone)}</div>${field('One-time instant (only for one-time schedules)','once',a.once||'','datetime-local','The one-time field uses your device timezone. Its stored instant is shown in the occurrence preview.')}<button class="select-link" data-act="preview-schedule" type="button">Preview next three occurrences</button><div id="schedule-preview" class="muted-box" style="margin:15px 0;display:none"></div>${sourcesPicker(a.sources)}<p class="small muted">Saved schedules start paused. Worker setup is required for unattended execution. Run now is available independently.</p>`,async(d,f)=>{if(d.once)d.once=new Date(d.once).toISOString();await mutate('automation-save',{...d,id:a.id,sources:new FormData(f).getAll('sources'),memory:$('[name=memory]',f).checked},'Schedule saved paused. Review worker health before enabling.');closeModal();},'Save routine');}
async function openSource(rid,version){const src=S.sources.find(x=>x.id===rid);if(!src||(version&&src.version!==Number(version))){modal('Source unavailable','<p class="dialog-intro">This source was deleted, excluded, or is no longer permitted. Its excerpt cannot be displayed.</p>');return;}modal(src.title,`<div class="row between">${badge(src.active?'Ready':'Excluded')}<span class="small muted">Version ${src.version} · ${fmt(src.created,true)}</span></div><p class="metadata small muted" style="margin-top:15px">${esc(src.origin)} · ${esc(src.type)}</p><div class="doc-body">${esc(src.text).replaceAll('\n','<br>')}</div><div class="foot-actions">${btn('Rename / edit text','edit-source',src.id)}${btn(src.active?'Exclude from retrieval':'Enable retrieval','toggle-source',src.id)}${btn('Replace file','replace-source',src.id)}${btn('Download','download-source',src.id)}</div>`,null,'',true);}
function download(name,data,type='application/json'){const b=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name.replace(/[<>:"/\\|?*]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
function uploadModal(replaceId){modal(replaceId?'Replace source safely':'A little more context.',`<p class="dialog-intro">Upload up to five TXT, Markdown, or selectable-text PDF files, up to 10 MB each. Processing happens before source text is saved. Scanned and encrypted PDFs need a text version.</p><div class="field"><label for="upload-files">Choose files</label><input id="upload-files" name="files" type="file" accept=".txt,.md,.markdown,.pdf" ${replaceId?'':'multiple'}></div><p class="small muted">Workspace-wide sources are available for explicit selection in future tasks. Uploads are never outgoing email attachments.</p><div id="upload-status" class="small muted" style="margin-top:17px"></div><hr class="divider"><p class="small muted">Or paste a short source directly.</p>${field('Source title','title')}${field('Text or Markdown','text','','textarea')}`,async(d,f)=>{const files=$('[name=files]',f).files;if(files.length>5)throw new Error('Choose up to five files.');if(!files.length){await api('source-save',{id:replaceId,title:d.title,text:d.text,type:'Text'});}else{for(const file of files){$('#upload-status').textContent='Processing '+file.name+'…';if(file.size>10*1024*1024)throw new Error(file.name+' exceeds 10 MB.');let value;const ext=file.name.split('.').pop().toLowerCase();if(['txt','md','markdown'].includes(ext))value=await file.text();else if(ext==='pdf'){try{const pdf=await import('/pdf.mjs');pdf.GlobalWorkerOptions.workerSrc='/pdf.worker.mjs';const document=await pdf.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;const pages=[];for(let i=1;i<=document.numPages;i++){const p=await document.getPage(i);const text=await p.getTextContent();pages.push('Page '+i+'\n'+text.items.map(x=>x.str).join(' '));}value=pages.join('\n\n');if(value.replace(/Page \d+/g,'').trim().length<10)throw new Error('No selectable text.');}catch(e){throw new Error('Could not extract '+file.name+'. Use an unencrypted PDF with selectable text, or upload TXT/Markdown.');}}else throw new Error('Unsupported file type: '+file.name);await api('source-save',{id:replaceId,title:d.title||file.name,text:value,type:ext==='pdf'?'PDF':ext==='txt'?'Text':'Markdown'});$('#upload-status').textContent=file.name+' · Ready';}}await refresh();closeModal();toast('Sources are ready for retrieval.');},'Process and save');}
function openRun(rid){const r=S.runs.find(x=>x.id===rid);if(!r)return;modal('Inside this run.',`<div class="row between"><h3>${esc(r.prompt)}</h3>${badge(r.state)}</div><div class="metadata small muted" style="margin:18px 0;line-height:2">Requested ${fmt(r.created,true)} · ${esc(S.settings.timezone)}<br>Started ${fmt(r.started,true)}<br>Completed ${fmt(r.completed,true)}<br>Model: ${esc(r.model||'Not called yet')}<br>Skill version: ${r.skillVersion||'No skill'}${r.test?' · safe test':''}<br>Saved run ID: ${r.id}</div>${r.error?'<div class="callout warn">'+esc(r.error)+'</div>':''}<h3 class="small">Source scope</h3><div style="margin-top:10px">${(r.sources||[]).map(src=>`<button class="source-chip" data-act="open-source" data-id="${src}">${esc(S.sources.find(x=>x.id===src)?.title||'Source unavailable')}</button>`).join('')||'<p class="small muted">No source documents selected.</p>'}</div><p class="small muted" style="margin-top:14px">Memory used: ${(r.memoryUsed||[]).map(mid=>esc(S.memories.find(m=>m.id===mid)?.text||'Now forgotten')).join(' · ')||'None recorded'}<br>Only concise execution facts are recorded; hidden model reasoning is not displayed.</p><div class="foot-actions">${r.document?btn('Open output','modal-open-doc',r.document,'primary'):''}${['Running','Queued'].includes(r.state)?btn('Pause','pause-run',r.id):''}${['Paused','Failed'].includes(r.state)?btn('Resume','resume-run',r.id):''}${!['Succeeded','Canceled'].includes(r.state)?btn('Cancel remaining work','cancel-run',r.id,'danger'):''}${btn('Export run','export-run',r.id)}${btn('Save as skill','save-run-skill',r.id)}</div>`,null,'',true);}
const actions={
 'close-modal':()=>requestClose(),menu:()=>$('#sidebar').classList.toggle('open'),
 demo:async()=>{closeModal();await api('demo');await refresh();go('home');},
 'leave-demo':async()=>{closeModal();await api('leave-demo');await refresh();go('home');toast('Returned to your private workspace. Demo data was removed.');},
 'reset-demo':()=>confirm('Start fresh in the demo?','This removes your current demo work and restores fictional fixtures. Your real workspace is unaffected.',async()=>{await mutate('reset-demo',{},'Demo restored.');go('home');},'Reset demo'),
 'new-chat':()=>{selectedChat=null;go('chat');},
 prepare:mid=>runModal('meeting',mid),followup:()=>runModal('followup'),daily:()=>runModal('daily'),
 'run-skill':kid=>runModal(kid),'test-skill':kid=>runModal(kid,'',true),
 'add-todo':()=>editTodo(),'edit-todo':tid=>editTodo(S.todos.find(t=>t.id===tid)),
 'toggle-todo':tid=>mutate('todo-toggle',{id:tid},'Task updated.'),
 'delete-todo':tid=>confirm('Delete this personal task?','This removes only the internal to-do. Its source material is unchanged.',()=>mutate('todo-delete',{id:tid},'Task deleted.'),'Delete task'),
 'add-memory':()=>editMemory(),'edit-memory':mid=>editMemory(S.memories.find(m=>m.id===mid)),
 'pin-memory':mid=>mutate('memory-pin',{id:mid},'Memory priority updated.'),
 'toggle-memory':mid=>mutate('memory-toggle',{id:mid},'Future retrieval updated.'),
 'delete-memory':mid=>confirm('Forget this memory?','It will be excluded from future model context immediately. Existing outputs and the original source may still contain this information.',()=>mutate('memory-delete',{id:mid},'Memory forgotten.'),'Forget memory'),
 upload:()=>uploadModal(),'replace-source':sid=>uploadModal(sid),
 'open-source':(sid,version)=>openSource(sid,version),
 'toggle-source':async sid=>{await mutate('source-toggle',{id:sid},'Source retrieval updated.');closeModal();},
 'edit-source':sid=>{const s=S.sources.find(x=>x.id===sid);if(!s)return;modal('Edit source text',`${field('Source title','title',s.title)}${field('Text','text',s.text,'textarea')}`,async d=>{await mutate('source-save',{...d,id:sid,type:s.type},'Source version updated.');closeModal();},'Save version',true);},
 'delete-source':sid=>modal('Remove source content?',`<p class="dialog-intro">The source text becomes unavailable to future retrieval. Existing references become unavailable. Dependent schedules require attention.</p><label class="checkbox"><input type="checkbox" name="associated">Also delete generated documents that cite this source, including mixed-source documents.</label>`,async(_,f)=>{await mutate('source-delete',{id:sid,associated:$('[name=associated]',f).checked},'Source removed.');closeModal();},'Delete source'),
 'open-doc':did=>{selectedDoc=did;page='library';location.hash='library';render();},
 'modal-open-doc':did=>{closeModal();actions['open-doc'](did);},
 'edit-doc':did=>editDoc(S.documents.find(d=>d.id===did)),
 'duplicate-doc':did=>mutate('document-duplicate',{id:did},'Document duplicated.'),
 'delete-doc':did=>confirm('Delete this document?','This invalidates its pending approvals. Sources and completed external effects remain.',()=>mutate('document-delete',{id:did},'Document deleted.'),'Delete document'),
 'download-doc':did=>{const d=S.documents.find(d=>d.id===did);if(d)download(d.title+'.md',d.text,'text/markdown');},
 'download-source':sid=>{const s=S.sources.find(s=>s.id===sid);if(s)download(s.title+'.txt',s.text,'text/plain');},
 'library-back':()=>{selectedDoc=null;render();},'library-page':()=>go('library'),
 'followup-from':did=>{const d=S.documents.find(d=>d.id===did);runModal('followup',S.runs.find(r=>r.id===d?.run)?.meeting);},
 'request-approval':async did=>{const result=await api('approval-create',{id:did});await refresh(false);selectedAction=result.action;go('approvals');toast('Review this exact version before sending.');},
 'review-approval':aid=>{selectedAction=aid;go('approvals');},
 'select-approval':aid=>{selectedAction=aid;render();},
 'approve-send':async aid=>{await api('send',{id:aid});await refresh();toast(S.actions.find(a=>a.id===aid)?.state==='Sent'?'Delivery confirmed. Receipt saved.':'Outcome unknown. Check status before taking further action.');},
 'deny-approval':aid=>mutate('approval-deny',{id:aid},'Send denied. No message was dispatched.'),
 'refresh-approval':async aid=>{const result=await api('approval-refresh',{id:aid});selectedAction=result.action;await refresh();toast('New preview created. Review before approving.');},
 reconcile:async aid=>{const r=await api('reconcile',{id:aid});await refresh();toast(r.found?'Confirmed sent message found.':'No confirmation yet. Repeat sending remains blocked.');},
 'approval-info':()=>modal('One approval. One exact action.',`<p class="dialog-intro">Before any email leaves Daylight, you review the complete recipient address, subject, and body. Approval applies only to that saved version and expires after 15 minutes.</p><p class="dialog-intro">Editing invalidates the previous preview. Denying a send keeps the draft. If delivery is uncertain, a repeat send remains blocked until the provider outcome is reconciled.</p>`),
 'new-skill':()=>editSkill(),'edit-skill':kid=>editSkill(S.skills.find(k=>k.id===kid)),
 'save-as-skill':did=>{const d=S.documents.find(x=>x.id===did);const r=S.runs.find(x=>x.id===d?.run);editSkill({name:'My '+(r?.skill?S.skills.find(k=>k.id===r.skill)?.name:'workflow'),description:'A reusable workflow for '+(r?.skill||'my work'),instructions:S.skills.find(k=>k.id===r?.skill)?.instructions||'Use the selected sources and supplied inputs to create a useful internal brief. Cite all sourced facts. Do not send messages.'});},
 'save-run-skill':rid=>{const r=S.runs.find(x=>x.id===rid);editSkill({name:'My workflow',description:'A reusable recipe for a useful internal output.',instructions:S.skills.find(k=>k.id===r?.skill)?.instructions||'Create a sourced internal brief from selected context. Never execute external writes.'});},
 'duplicate-skill':kid=>mutate('skill-duplicate',{id:kid},'Personal draft created. Edit and test before activation.'),
 'activate-skill':kid=>mutate('skill-state',{id:kid,state:'Active'},'Skill active.'),
 'disable-skill':kid=>mutate('skill-state',{id:kid,state:'Disabled'},'Skill disabled. Dependent schedules paused.'),
 'delete-skill':kid=>confirm('Delete this personal skill?','Dependent schedules will require attention. Historical runs keep their recorded skill version.',()=>mutate('skill-delete',{id:kid},'Skill deleted.'),'Delete skill'),
 'new-automation':()=>editAutomation(),'edit-automation':aid=>editAutomation(S.automations.find(a=>a.id===aid)),
 'toggle-automation':async aid=>{const a=S.automations.find(x=>x.id===aid);if(a?.state!=='Enabled'&&!S.setup.heartbeat){modal('Connect the background worker first.',`<p class="dialog-intro">Your routine is saved. There is no worker heartbeat yet, so unattended execution cannot be confirmed. Use Run now to test the workflow, or finish the scheduler setup in Settings.</p><div class="foot-actions">${btn('Open deployment setup','deployment-modal','','primary')}</div>`);return;}await mutate('automation-toggle',{id:aid},'Schedule updated. Missed occurrences are not replayed.');},
 'run-automation':aid=>ensureDisclosure(async()=>{await api('automation-run',{id:aid});await refresh();tab='runs';go('tasks');toast('Workflow started. The next scheduled time is unchanged.');}),
 'delete-automation':aid=>confirm('Delete this schedule?','Future triggers stop. A run that has already started continues; cancel it separately from Tasks. Its history remains.',()=>mutate('automation-delete',{id:aid},'Schedule deleted.'),'Delete schedule'),
 'preview-schedule':async()=>{const f=$('#modal-form');const d=dataOf(f);if(d.once)d.once=new Date(d.once).toISOString();const r=await api('preview-schedule',d);$('#schedule-preview').style.display='block';$('#schedule-preview').innerHTML=r.occurrences.map(t=>esc(new Intl.DateTimeFormat('en-GB',{timeZone:d.timezone,dateStyle:'full',timeStyle:'short'}).format(t))+' · '+esc(d.timezone)).join('<br>')||'No future occurrences. Check the date and time.';},
 'pause-all':()=>confirm(S.settings.paused?'Lift the global pause?':'Pause all work?',S.settings.paused?'Individual schedules remain paused until you review and resume them. Missed runs and old approvals will not replay.':'Queued and subsequent work stops. Pending approvals become invalid. An in-flight provider call may still finish and its outcome will be recorded.',()=>mutate('pause-all',{},S.settings.paused?'Global pause lifted. Review schedules before resuming.':'All work paused.'),S.settings.paused?'Lift pause':'Pause all'),
 'open-run':rid=>openRun(rid),
 'pause-run':async rid=>{await mutate('run-state',{id:rid,state:'Paused'},'Paused before the next step. In-flight calls may finish.');closeModal();},
 'resume-run':async rid=>{await mutate('run-state',{id:rid,state:'Queued'},'Run queued after checking current access.');closeModal();},
 'cancel-run':rid=>confirm('Cancel remaining work?','Unexecuted steps and pending approvals will stop. Completed effects remain in the record.',async()=>{await mutate('run-state',{id:rid,state:'Canceled'},'Remaining work canceled.');closeModal();},'Cancel run'),
 'export-run':rid=>{const r=S.runs.find(x=>x.id===rid);download('daylight-run-'+rid+'.json',{run:r,output:S.documents.find(d=>d.id===r?.document),actions:S.actions.filter(a=>a.run===rid)});},
 'regenerate':rid=>{const r=S.runs.find(x=>x.id===rid);if(r)ensureDisclosure(()=>startRun({...r,id:undefined}));},
 'select-chat':cid=>{selectedChat=cid;render();},
 'toggle-archived':()=>{archived=!archived;render();},
 'rename-chat':cid=>{const c=S.chats.find(x=>x.id===cid);modal('Rename conversation',field('Title','title',c?.title),async d=>{await mutate('chat-rename',{id:cid,title:d.title},'Conversation renamed.');closeModal();});},
 'archive-chat':cid=>mutate('chat-archive',{id:cid},'Conversation visibility updated.'),
 'delete-chat':cid=>confirm('Delete this conversation?','The conversation entry is removed. Saved documents, explicit memories, run records, and action receipts remain. Use workspace deletion for broader app-held removal.',async()=>{await mutate('chat-delete',{id:cid},'Conversation deleted.');selectedChat=null;render();},'Delete conversation'),
 'calendar-settings':()=>{settingsTab='connections';go('settings');},
 'connections-modal':()=>{closeModal();settingsTab='connections';go('settings');},
 'deployment-modal':()=>{closeModal();settingsTab='deployment';go('settings');},
 connect:service=>{if(S.demo){toast('Leave demo to connect a real Google account.');return;}const c=S.connections[service];modal('Choose your '+(service==='gmail'?'Gmail':'Calendar')+' access',`<p class="dialog-intro">Authorize one Google account. Provider grants are separate from these application-enforced filters. Source selection applies before retrieval.</p>${service==='gmail'?field('Allowed Gmail label IDs · comma separated','labels',c.labels.join(', '),'text','Use provider label IDs, such as INBOX or Label_123.'):field('Allowed calendar IDs · comma separated','calendars',c.calendars.join(', '),'text','Use primary or exact calendar IDs from Google Calendar settings.')}${service==='gmail'?`<label class="checkbox"><input type="checkbox" name="send" ${c.send?'checked':''}>Request Gmail send capability separately. Every send still needs exact approval.</label>`:''}<p class="small muted">Changing these filters invalidates pending approvals. One account is supported. Setup requires operator-provided OAuth credentials.</p>`,async(d,f)=>{const result=await api('connect',{service,labels:(d.labels||'').split(',').map(x=>x.trim()).filter(Boolean),calendars:(d.calendars||'').split(',').map(x=>x.trim()).filter(Boolean),send:!!$('[name=send]',f)?.checked});location.href=result.url;},'Continue to Google');},
 sync:service=>mutate('sync',{service},'Permitted source context refreshed.'),
 disconnect:()=>confirm('Disconnect your Google account?','Both Google services share the account. App-held credentials, cached emails, and events are removed. Dependent schedules pause. Generated documents and saved memories remain. Remove the app’s grant in Google account settings as well.',()=>mutate('disconnect',{},'Google disconnected from Daylight.'),'Disconnect'),
 disclosure:()=>{const prior=S.settings.disclosure;modal('Processing, with your consent.',`<p class="dialog-intro">Selected source content, your request, and active eligible memories are sent to Nebius Token Factory when you request live generation. Daylight uses hosted infrastructure. It does not claim local-only processing.</p><label class="checkbox"><input type="checkbox" name="accepted" ${prior?'checked':''}>Allow live model requests with the selected context.</label>`,async(_,f)=>{await mutate('settings',{settings:{disclosure:$('[name=accepted]',f).checked}},'Processing preference saved.');closeModal();});},
 profile:()=>{settingsTab='profile';go('settings');},
 'export-workspace':async()=>{download('daylight-workspace-'+new Date().toISOString().slice(0,10)+'.json',await api('export'));toast('Snapshot downloaded. Credentials excluded.');},
 'export-activity':()=>download('daylight-activity.json',{snapshot:new Date().toISOString(),activity:S.activity}),
 erase:()=>modal('Delete your workspace data?',`<p class="dialog-intro">This deletes active workspace data, linked demo sessions, and stored Google credentials. External email and downloaded files are unaffected. Hosting backup expiry and session invalidation remain unverified. This operation cannot be undone.</p>${field('Type your display name to confirm: '+S.settings.name,'confirm')}`,async d=>{await api('erase',d);closeModal();await refresh();go('home');toast('Active app-held data deleted.');},'Delete active data'),
 notifications:()=>{const muted=!S.settings.notifications;modal('Your inbox',`${S.notifications.length?S.notifications.map(n=>`<button class="notification-item" type="button" data-act="open-notification" data-id="${n.id}"><span class="tile-icon ${n.read?'green':'orange'}">${icon(n.target==='approvals'?'shield':'file')}</span><span>${esc(S.settings.generic?'Your workspace has an update':n.title)}<p>${ago(n.created)} · ${n.read?'Read':'Unread'}</p></span></button>`).join(''):'<p class="dialog-intro">No updates yet. Completed work and required approvals will appear here.</p>'}<div class="foot-actions">${btn('Mark all read','notifications-read')}</div>`);},
 'notifications-read':async()=>{await mutate('notification-read',{},'Notifications marked read.');closeModal();},
 'open-notification':async nid=>{const n=S.notifications.find(x=>x.id===nid);await api('notification-read',{id:nid});closeModal();await refresh(false);go(n?.target||'home');},
 search:()=>modal('Find something in your workspace.',`<input class="input-search" id="global-search" placeholder="Search briefs, tasks, memories, skills…" aria-label="Global workspace search" style="width:100%"><div id="search-results" class="search-results"><p class="small muted">Search only your saved workspace records. Connected accounts are not searched globally.</p></div>`),
 'search-open':key=>{const [type,rid]=key.split('|');closeModal();if(type==='documents')actions['open-doc'](rid);else if(type==='sources')openSource(rid);else if(type==='chats'){selectedChat=rid;go('chat');}else go({todos:'tasks',memories:'memory',skills:'skills',automations:'automations'}[type]||'home');}
};
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-page]');if(!b)return;if(b.dataset.page){closeModal();go(b.dataset.page);return;}if(b.dataset.tab){tab=b.dataset.tab;taskFilter='all';render();return;}if(b.dataset.libraryTab){libraryTab=b.dataset.libraryTab;render();return;}if(b.dataset.settingsTab){settingsTab=b.dataset.settingsTab;render();return;}const act=b.dataset.act;if(!act||!actions[act])return;e.preventDefault();if(b.disabled)return;b.disabled=true;try{await actions[act](b.dataset.id,b.dataset.version);}catch(error){const err=$('#modal-error');if($('#modal').open&&err){err.textContent=error.message;err.classList.add('visible');}else toast(error.message);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const submit=$('button[type=submit]',f);if(submit?.disabled)return;if(submit)submit.disabled=true;try{const d=dataOf(f);if(f.id==='modal-form'&&modalSubmit){$('#modal-error')?.classList.remove('visible');await modalSubmit(d,f);}else if(['home-composer','chat-composer'].includes(f.id)){if(!d.prompt?.trim())throw new Error('Add a request first.');if(/\b(prep|prepare)\b.*\b(meeting|maya)\b/i.test(d.prompt)){runModal('meeting',S.meetings.find(m=>d.prompt.toLowerCase().includes(m.person.split(' ')[0].toLowerCase()))?.id);return;}if(/\b(follow.?up|follow up)\b/i.test(d.prompt)){runModal('followup');return;}if(/\b(daily brief|plan my day)\b/i.test(d.prompt)){runModal('daily');return;}if(/^remember (that )?/i.test(d.prompt)){editMemory({text:d.prompt.replace(/^remember (that )?/i,'')});return;}const sourceList=f.id==='chat-composer'?new FormData(f).getAll('sources'):S.sources.filter(x=>x.active).map(x=>x.id);const prompt=d.prompt;await ensureDisclosure(()=>startRun({prompt,sources:sourceList,memory:f.id==='home-composer'?S.settings.memory:$('[name=memory]',f).checked}));}else if(f.id==='profile-form')await mutate('settings',{settings:d},'Preferences saved.');else if(f.id==='notifications-form')await mutate('settings',{settings:{notifications:$('[name=notifications]',f).checked,generic:$('[name=generic]',f).checked}},'Notification preferences saved.');else if(f.id==='usage-form')await mutate('settings',{settings:{tokenLimit:Number(d.tokenLimit)}},'Workspace ceiling updated.');}catch(error){const err=$('#modal-error');if($('#modal').open&&err){err.textContent=error.message;err.classList.add('visible');}else toast(error.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='filter'){const pos=e.target.selectionStart;filter=e.target.value.toLowerCase();render();const f=$('#filter');f.focus();f.setSelectionRange(pos,pos);}if(e.target.id==='global-search'){const term=e.target.value.toLowerCase().trim();const results=[];for(const type of ['documents','sources','todos','memories','skills','automations','chats'])for(const r of S[type]){const title=r.title||r.name||r.text;if(term&&(title+' '+(r.type||'')).toLowerCase().includes(term))results.push({type,id:r.id,title});}$('#search-results').innerHTML=results.length?results.slice(0,25).map(r=>`<button class="search-result" data-act="search-open" data-id="${r.type}|${r.id}"><span>${esc(r.title)}</span><span class="muted small">${r.type}</span></button>`).join(''):'<p class="small muted">'+(term?'No matching workspace records. Try a shorter phrase.':'Search only your saved workspace records.')+'</p>';}});
document.addEventListener('change',async e=>{if(e.target.id==='task-filter'){taskFilter=e.target.value;render();}if(e.target.id==='global-memory'){try{await mutate('settings',{settings:{memory:e.target.checked}},'Memory use updated.');}catch(err){toast(err.message);}}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();actions.search();}if(e.key==='Escape')$('#sidebar')?.classList.remove('open');if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)&&e.target.tagName==='TEXTAREA')e.target.form?.requestSubmit();});
$('#modal').addEventListener('close',()=>{lastFocus?.focus();});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==page){page=p;filter='';selectedDoc=null;render();}});
window.addEventListener('online',()=>refresh().catch(e=>toast(e.message)));
window.addEventListener('offline',()=>toast('You’re offline. Saved work is preserved. Reconnect before submitting.'));
try{await refresh();if(location.search.includes('connection=')){settingsTab='connections';go('settings');toast(location.search.includes('denied')?'Google access was canceled. No connection was added.':'Google account connected. Refresh selected sources to retrieve context.');history.replaceState(null,'',location.pathname+'#settings');}}catch(e){$('#app').innerHTML=`<div class="loading"><div style="text-align:center;max-width:500px;padding:25px">${mark()}<h2 style="margin:20px">Your workspace is waiting.</h2><p class="muted">${esc(e.message)}</p><div style="margin-top:25px"><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in</a><button class="btn" onclick="location.reload()">Retry</button><button class="btn" id="recover-demo">Leave expired demo</button></div></div></div>`;$('#recover-demo').onclick=async()=>{await api('leave-demo');location.reload();};}

function notificationAttention(){if(!S.settings.notifications)return false;const time=new Intl.DateTimeFormat('en-GB',{timeZone:S.settings.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const a=S.settings.quietStart,b=S.settings.quietEnd;const quiet=a&&b&&(a>b?(time>=a||time<b):(time>=a&&time<b));return !quiet&&S.notifications.some(n=>!n.read);}
function requestClose(){if(!modalDirty){closeModal();return;}const dialog=$('#modal');const held=[...dialog.childNodes];const submit=modalSubmit;modal('Keep your changes?', '<p class="dialog-intro">This editor has unsaved changes. Save them, discard them, or keep editing.</p><div class="foot-actions"><button class="btn" data-dirty-choice="stay" type="button">Stay</button><button class="btn danger" data-dirty-choice="discard" type="button">Discard changes</button><button class="btn primary" data-dirty-choice="save" type="button">Save changes</button></div>');for(const b of $$('[data-dirty-choice]',dialog))b.onclick=()=>{if(b.dataset.dirtyChoice==='discard'){closeModal();return;}dialog.replaceChildren(...held);modalSubmit=submit;modalDirty=true;if(b.dataset.dirtyChoice==='save')$('#modal-form').requestSubmit();};}
document.addEventListener('input',e=>{if(e.target.closest('#modal-form')&&e.target.id!=='global-search')modalDirty=true;});
document.addEventListener('change',e=>{if(e.target.closest('#modal-form'))modalDirty=true;});
$('#modal').addEventListener('cancel',e=>{if(modalDirty){e.preventDefault();requestClose();}});
window.addEventListener('beforeunload',e=>{if(modalDirty){e.preventDefault();e.returnValue='';}});
